  "verses": [
    {
      "chapter": 7,
      "text_ar": "طَارَ النَّسْرُ وَجَاءَ إِلَى أُورُشَلِيمَ وَأَعْطَى الرِّسَالَةَ لَبَارُوخَ؛ وَلَمَّا حَلَّهَا قَرَأَهَا وَقَبَّلَهَا وَبَكَى عِنْدَمَا سَمِعَ عَنْ ضِيقِ الشَّعْبِ وَمَعَانَاتِهِمْ.",
      "verse": 36
    },
    {
      "chapter": 7,
      "text_ar": "أَمَّا إِرْمِيَا فَأَخَذَ التِّينَ وَوَزَّعَهُ عَلَى الْمَرْضَى بَيْنَ الشَّعْبِ، وَظَلَّ يُعَلِّمُهُمْ أَنْ يَمْتَنِعُوا عَنْ م مَارَسَاتِ أُمَمِ بَابِلَ الْمُنَجِّسَةِ.",
      "verse": 37
    }
  ]
}
